-- ==========================================================================
--  Lucky Traders — demo catalog seed
--  123 categories · 63 brands · 293 products
--  Generated by `npm run seed:sql`. Run supabase/schema.sql first.
--  Safe to re-run: every statement upserts on its unique slug.
-- ==========================================================================

begin;

-- --------------------------------------------------------- categories
on conflict (slug) do update set name = excluded.name, name_si = excluded.name_si, name_ta = excluded.name_ta, icon = excluded.icon, is_active = excluded.is_active, sort_order = excluded.sort_order;

on conflict (slug) do update set name = excluded.name, name_si = excluded.name_si, name_ta = excluded.name_ta, parent_id = excluded.parent_id, is_active = excluded.is_active, sort_order = excluded.sort_order;

-- ------------------------------------------------------------- brands
on conflict (slug) do update set name = excluded.name, is_active = excluded.is_active;

-- ----------------------------------------------------------- products
on conflict (slug) do update set sku = excluded.sku, name = excluded.name, name_si = excluded.name_si, name_ta = excluded.name_ta, description = excluded.description, category_id = excluded.category_id, subcategory_id = excluded.subcategory_id, brand_id = excluded.brand_id, price = excluded.price, sale_price = excluded.sale_price, stock = excluded.stock, unit = excluded.unit, weight = excluded.weight, is_featured = excluded.is_featured, is_new = excluded.is_new, is_best_seller = excluded.is_best_seller, is_active = excluded.is_active, popularity = excluded.popularity;

